function my_noise(pt) {
	return 2*noise(noise_scale*pt.x, noise_scale*pt.y, noise_scale*pt.z)-1;
}

class Point {
	constructor() {
		this.p = new p5.Vector.random3D().mult(R);
			this.c = "#"+random(palette);
	}
	move() {
		var speed = createVector(this.p.y, -this.p.x, this.p.y).mult(1/R);
		this.p.add(speed.mult(2)).normalize().mult(R);
	}
	draw() {
		stroke(this.c);
		strokeWeight(map(this.p.x, -R, R, 3, 10));
